let state=null, route='dashboard', lastPlanDiagnostics=null;
const main=document.getElementById('main'), nav=document.getElementById('nav'), modal=document.getElementById('modal'), modalBody=document.getElementById('modalBody'), searchOverlay=document.getElementById('searchOverlay');
const fmtDate=(x,withTime=false)=>x?new Date(x).toLocaleString(undefined,withTime?{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}:{year:'numeric',month:'short',day:'numeric'}):'—';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const statusTone=s=>/Verified|Approved|Released|Closed|Completed|Available|Valid|Pass|On Track|Ready/.test(s)?'green':/Failed|Expired|Breakdown|Overdue|Late/.test(s)?'red':/Blocked|At Risk|Due|Maintenance|Awaiting|Rework/.test(s)?'amber':/Planned|In Progress|Reserved|High/.test(s)?'blue':'grey';
