 const qualified=state.staff.filter(s=>(s.qualifications||[]).some(q=>q.methodId===l.methodId&&['Independent','Reviewer','Trainer/Expert'].includes(q.level))&&(s.equipmentQualifications||[]).includes(m?.equipmentType));
