function applyBuilderTemplate(id){const templates={env:['ELEC-001','ENV-TC-004','ENV-HU-003','ELEC-002'],reliability:['ELEC-001','MECH-VIB-006','REL-005','MECH-DUR-009','ELEC-002'],electrical:['ELEC-001','SCOPE-003','FUNC-004','SW-009']},ids=templates[id]||[];const d=getBuilderDraft();d.selected={};for(const mid of ids)if(state.methods.some(m=>m.id===mid&&m.active))d.selected[mid]={staffId:'',staffPolicy:'Auto'};persist().then(()=>{render();toast(`${ids.length} released methods loaded from template.`)})}

function costSettingsModal(){const c=state.settings.costFramework;openModal(`<h2>Test Cost Framework</h2><p class="small muted">Internal demo charge rates support transparent planning estimates; they are not accounting-system postings.</p><div class="modal-grid"><div class="field"><label>Currency</label><select id="cfCurrency">${['EUR','USD','GBP'].map(x=>`<option ${c.currency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Overhead (%)</label><input id="cfOver" type="number" min="0" max="100" value="${c.overheadPct}"></div><div class="field"><label>Planning contingency (%)</label><input id="cfCont" type="number" min="0" max="100" value="${c.contingencyPct}"></div><div class="field"><label>Default staff rate / h</label><input id="cfStaff" type="number" min="0" value="${c.defaultStaffRate}"></div><div class="field"><label>Default equipment rate / h</label><input id="cfEq" type="number" min="0" value="${c.defaultEquipmentRate}"></div></div><button id="saveCostFramework" class="btn primary">Save Cost Framework</button>`);document.getElementById('saveCostFramework').onclick=async()=>{const old=JSON.stringify(c);Object.assign(c,{currency:document.getElementById('cfCurrency').value,overheadPct:Number(document.getElementById('cfOver').value)||0,contingencyPct:Number(document.getElementById('cfCont').value)||0,defaultStaffRate:Number(document.getElementById('cfStaff').value)||0,defaultEquipmentRate:Number(document.getElementById('cfEq').value)||0});state.audit.push(audit('Cost framework changed','Settings',old,JSON.stringify(c)));await persist();closeModal();render();toast('Cost framework updated.')};}

function editCostBudgetModal(id){const p=state.programmes.find(x=>x.id===id);if(!p)return;const C=programmeCost(state,id);openModal(`<h2>${id} · Budget & Cost Target</h2><div class="grid kpi compact-kpis">${kpiCard('Current budget',currency(state,C.budget,true),'Financial guardrail')}${kpiCard('Forecast',currency(state,C.forecast,true),`${C.variance>=0?'+':''}${C.variancePct}% variance`)}${kpiCard('Actual to date',currency(state,C.actualToDate,true),'Completed work')}${kpiCard('Estimate to complete',currency(state,C.remaining,true),'Open work')}</div><div class="modal-grid"><div class="field"><label>Programme budget</label><input id="budgetValue" type="number" min="0" value="${Number(p.budget)||C.budget}"></div><div class="field"><label>Business priority score</label><input id="budgetPriority" type="number" min="0" max="100" value="${Number(p.businessPriority)||50}"></div></div><div class="field"><label>Reason / financial note</label><textarea id="budgetReason">Budget reviewed against current test scope and resource plan.</textarea></div><div class="actions"><button id="saveBudget" class="btn primary">Save Budget & Recalculate Cost</button></div>`);document.getElementById('saveBudget').onclick=async()=>{const old=p.budget;p.budget=Math.max(0,Number(document.getElementById('budgetValue').value)||0);p.businessPriority=Math.max(0,Math.min(100,Number(document.getElementById('budgetPriority').value)||0));p.changeReason=document.getElementById('budgetReason').value.trim();state.audit.push(audit('Programme budget changed',id,old,p.budget));await persist();closeModal();render();toast(`${id} budget updated to ${currency(state,p.budget,true)}.`)}}

async function builderAddCustom(){const d=getBuilderDraft(),name=document.getElementById('bcName')?.value.trim();if(!name)return toast('Enter a name for the new test.');const tempId=`CUSTOM-${Date.now().toString().slice(-6)}`;d.customMethods.push({tempId,name,category:document.getElementById('bcCat').value,equipmentType:document.getElementById('bcEq').value,skill:document.getElementById('bcSkill').value,executionHours:Number(document.getElementById('bcHours').value)||8,devDays:Number(document.getElementById('bcDays').value)||7,engineeringHours:Number(document.getElementById('bcEng').value)||40,technicianHours:16,fixtureCost:Number(document.getElementById('bcFixture').value)||0,staffId:'',staffPolicy:'Auto'});await persist();render();toast('Development-gated test added to builder.');}
async function builderRemoveCustom(id){const d=getBuilderDraft();d.customMethods=(d.customMethods||[]).filter(x=>x.tempId!==id);await persist();render();}
