function showSpecImpact(id){const sp=state.specifications.find(x=>x.id===id);if(!sp)return;const r=specificationReadiness(sp),bookings=state.bookings.filter(b=>r.legs.some(l=>l.id===b.legId)&&new Date(b.end)>DEMO_NOW),dev=r.legs.filter(l=>l.developmentTaskId&&!state.devTasks.find(d=>d.id===l.developmentTaskId)?.completeDate);openModal(`<h2>${sp.id} · Change Impact</h2><p class="small muted">Use this before changing revision/status. It shows what operational demand depends on the specification.</p><div class="grid kpi compact-kpis">${kpiCard('Requirements affected',r.reqs.length,'Traceability links')}${kpiCard('Test legs affected',r.legs.length,`${r.activeLegs} still open`)}${kpiCard('Future bookings',bookings.length,'Would need review after a material change')}${kpiCard('Development tasks',dev.length,'Unreleased methods linked')}${kpiCard('Historical spec issues',r.issues.length,`${r.issues.reduce((a,i)=>a+(Number(i.delayHours)||0),0)}h delay`)}${kpiCard('Readiness',`${r.score}%`,sp.status)}</div><h3>Affected future work</h3><div class="table-wrap"><table><thead><tr><th>Leg</th><th>Method</th><th>Status</th><th>Planned</th><th>Equipment / Staff</th></tr></thead><tbody>${r.legs.filter(l=>l.status!=='Completed').map(l=>`<tr><td>${l.id} · ${esc(l.name)}</td><td>${l.methodId}</td><td>${pill(l.status)}</td><td>${fmtDate(l.plannedStart,true)}</td><td>${l.equipmentId||'—'} / ${state.staff.find(s=>s.id===l.staffId)?.name||'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No future affected test legs.</td></tr>'}</tbody></table></div><div class="callout warning"><strong>Prototype change-control rule:</strong> a released specification changed to Draft/Review will automatically gate affected future planning until it is re-released. Completed evidence remains historical.</div>`)}
function openSpecReviewModal(id){const sp=state.specifications.find(x=>x.id===id);if(!sp)return;const labels={sourceTraceability:'Source requirement and revision traceability are clear',requirementsMapped:'Validation requirements are mapped',acceptanceCriteria:'Acceptance limits / pass-fail basis are objective',sampleDefinition:'Sample population, conditions and sequence are defined',methodRevision:'Referenced test methods/revisions are identified',releaseApproval:'Quality/release approval is complete'},c=sp.reviewChecks||{};openModal(`<h2>${sp.id} · Specification Readiness Review</h2><p class="small muted">The readiness gate deliberately asks whether the document can safely drive executable laboratory demand.</p><div class="review-checks">${Object.entries(labels).map(([k,l])=>`<label class="review-check"><input type="checkbox" data-review="${k}" ${c[k]?'checked':''}><span><strong>${esc(l)}</strong><small>${k==='releaseApproval'?'Required before status can be Released.':'Contributes to operational readiness score.'}</small></span></label>`).join('')}</div><div class="modal-grid"><div class="field"><label>Revision</label><input id="srRevision" value="${esc(sp.revision)}"></div><div class="field"><label>Desired status</label><select id="srStatus">${['Draft','Review','Released','Obsolete'].map(x=>`<option ${sp.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Owner</label><select id="srOwner">${state.staff.map(s=>`<option ${s.name===sp.owner?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div></div><div class="actions"><button id="saveSpecReview" class="btn primary">Save Review & Recalculate Plan</button></div>`);document.getElementById('saveSpecReview').onclick=async()=>{const checks=Object.fromEntries([...modalBody.querySelectorAll('[data-review]')].map(x=>[x.dataset.review,x.checked])),score=Math.round(Object.values(checks).filter(Boolean).length/Object.keys(checks).length*100),desired=document.getElementById('srStatus').value;if(desired==='Released'&&(!checks.releaseApproval||score<80))return toast('Release rejected: complete approval and achieve at least 80% readiness.');const old=`${sp.revision} ${sp.status} ${sp.qualityScore}%`;sp.reviewChecks=checks;sp.revision=document.getElementById('srRevision').value.trim()||sp.revision;sp.status=desired;sp.owner=document.getElementById('srOwner').value;sp.qualityScore=score;sp.qualityFlags=Object.entries(labels).filter(([k])=>!checks[k]).map(([,v])=>v);state.audit.push(audit('Specification readiness reviewed',sp.id,old,`${sp.revision} ${sp.status} ${score}%`));const plan=scheduleAll(state);state=plan.data;lastPlanDiagnostics=plan.diagnostics;state.settings.planDirty=false;await persist();closeModal();render();toast(`${sp.id} saved at ${score}% readiness; ${plan.diagnostics.moved.length} bookings moved.`)}}
function uploadSpecModal(){openModal(`<h2>Upload Test Specification</h2><p class="small muted">Upload the controlled test basis, then run the readiness review before using it to release laboratory demand.</p><div class="modal-grid"><div class="field"><label>Programme</label><select id="upSpecProg">${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)} · ${esc(p.product)}</option>`).join('')}</select></div><div class="field"><label>Specification ID</label><input id="upSpecId" value="SPEC-${String((state.specifications||[]).length+1).padStart(3,'0')}"></div><div class="field"><label>Name</label><input id="upSpecName" value="Validation Test Specification"></div><div class="field"><label>Revision</label><input id="upSpecRev" value="R1"></div><div class="field"><label>Category</label><select id="upSpecCat"><option>Product Validation</option><option>Environmental</option><option>Electrical</option><option>Mechanical</option><option>Reliability</option><option>EMC</option><option>Test Method</option></select></div><div class="field"><label>Initial status</label><select id="upSpecStatus"><option>Review</option><option>Draft</option><option>Released</option></select></div><div class="field"><label>Owner</label><select id="upSpecOwner">${state.staff.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Effective date</label><input id="upSpecDate" type="date" value="${DEMO_NOW.toISOString().slice(0,10)}"></div><div class="field"><label>Primary test method (optional)</label><select id="upSpecMethod"><option value="">Programme methods automatically linked</option>${state.methods.map(m=>`<option value="${m.id}">${m.id} · ${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label>Specification file</label><input id="upSpecFile" type="file" accept=".pdf,.doc,.docx,.txt,.csv,image/*"></div></div><div class="field"><label>Acceptance basis / notes</label><textarea id="upSpecBasis">Released limits, sample population, sequence and acceptance criteria.</textarea></div><div class="callout">The file is stored browser-locally. The metadata is immediately linked to programme requirements and methods; use Review / Release to validate operational readiness.</div><div class="actions" style="margin-top:14px"><button id="saveSpec" class="btn primary">Save Specification & Open Review</button></div>`);document.getElementById('saveSpec').onclick=async()=>{const file=document.getElementById('upSpecFile').files[0];if(!file)return toast('Select a specification file to upload.');if(file.size>8*1024*1024)return toast('For this prototype, keep uploaded specifications below 8 MB.');const id=document.getElementById('upSpecId').value.trim();if(!id)return toast('Specification ID is required.');if(state.specifications.some(x=>x.id===id))return toast('Specification ID already exists.');const pid=document.getElementById('upSpecProg').value,method=document.getElementById('upSpecMethod').value,fileData=await fileToDataURL(file),reqIds=state.requirements.filter(r=>r.programmeId===pid).map(r=>r.id),methodIds=[...new Set([...state.legs.filter(l=>l.programmeId===pid).map(l=>l.methodId),...(method?[method]:[])])],desired=document.getElementById('upSpecStatus').value;const sp={id,programmeId:pid,name:document.getElementById('upSpecName').value.trim()||file.name,revision:document.getElementById('upSpecRev').value.trim()||'R1',category:document.getElementById('upSpecCat').value,status:desired==='Released'?'Review':desired,owner:document.getElementById('upSpecOwner').value,effectiveDate:new Date(document.getElementById('upSpecDate').value+'T08:00:00Z').toISOString(),uploadedAt:new Date().toISOString(),source:'User upload',acceptanceBasis:document.getElementById('upSpecBasis').value.trim(),description:'Browser-local uploaded test specification.',linkedMethodIds:methodIds,linkedRequirementIds:reqIds,documentName:file.name,documentPath:null,mimeType:file.type||'application/octet-stream',fileData,qualityScore:desired==='Released'?83:67,qualityFlags:desired==='Released'?['Release review still required in prototype workflow']:['Document requires readiness review'],reviewChecks:{sourceTraceability:true,requirementsMapped:reqIds.length>0,acceptanceCriteria:!!document.getElementById('upSpecBasis').value.trim(),sampleDefinition:false,methodRevision:methodIds.length>0,releaseApproval:false}};state.specifications.push(sp);for(const r of state.requirements.filter(r=>r.programmeId===pid))r.specificationId=id;state.documents.push({id:`DOC-${id}`,type:'Test Specification',entityId:id,name:sp.name,path:`embedded:${id}`});state.audit.push(audit('Test specification uploaded',id,'',`${file.name} · ${sp.revision}`));await persist();closeModal();render();openSpecReviewModal(id)}}

function renderProgrammes(){const P=portfolioCost(state);return pageHead('Validation Programmes','Prioritise programmes, control release gates, inspect cost/readiness and drill into project-specific laboratory planning',`<button class="btn" data-act="replan">↻ Recalculate Laboratory Plan</button><button class="btn primary" data-act="jump-builder">＋ Build Test Programme</button>`)+`<div class="grid kpi compact-kpis">${kpiCard('Programmes',state.programmes.length,`${state.programmes.filter(p=>p.gateStatus==='Released').length} released`)}${kpiCard('Portfolio budget',currency(state,P.totalBudget,true),'Programme budget control')}${kpiCard('Forecast cost',currency(state,P.totalForecast,true),`${P.programmes.filter(x=>x.variance>0).length} over budget`)}${kpiCard('At risk',state.programmes.filter(p=>['At Risk','Late','Blocked'].includes(p.scheduleRisk)).length,'Schedule constraint')}${kpiCard('Methods in development',state.devTasks.filter(d=>!d.completeDate).length,'Development gates')}${kpiCard('Readiness <100%',state.programmes.filter(p=>programmeReadiness(p.id).score<100).length,'Release/readiness attention')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Programme</th><th>Customer / Product</th><th>Owner</th><th>Gate</th><th>Priority</th><th>Due / Forecast</th><th>Risk</th><th>Readiness</th><th>Budget / Forecast</th><th>Progress</th><th>Plan</th></tr></thead><tbody>${state.programmes.map(p=>{const ls=state.legs.filter(l=>l.programmeId===p.id),done=ls.filter(l=>l.status==='Completed').length,pc=programmeCost(state,p.id),R=programmeReadiness(p.id);return `<tr><td><span class="link mono" data-entity="programme" data-id="${p.id}">${p.id}</span><div><strong>${esc(p.project)}</strong></div><div class="small muted">${esc(p.storyline)}</div></td><td>${esc(p.customer)}<div class="small muted">${esc(p.product)} · ${p.productRevision}</div></td><td>${esc(p.owner)}</td><td>${pill(p.gateStatus)}</td><td><select class="priority-change" data-id="${p.id}">${['Critical','High','Normal','Low'].map(x=>`<option ${x===p.priority?'selected':''}>${x}</option>`).join('')}</select><div class="small muted">score ${p.businessPriority}</div></td><td>${fmtDate(p.dueDate)}<div class="small muted">forecast ${fmtDate(p.forecastCompletion)}</div></td><td>${pill(p.scheduleRisk||p.status)}</td><td><strong>${R.score}%</strong><div class="progress"><span style="width:${R.score}%"></span></div></td><td>${currency(state,pc.budget,true)}<div class="small muted">forecast ${currency(state,pc.forecast,true)} · ${pc.variancePct>=0?'+':''}${pc.variancePct}%</div></td><td>${done}/${ls.length}<div class="progress"><span style="width:${pct(done,ls.length)}%"></span></div></td><td><button class="btn small" data-act="open-project-plan" data-id="${p.id}">Plan</button></td></tr>`}).join('')}</tbody></table></div></section>`}

function renderPlanning(){const m=computePlanningMetrics(state),active=(state.disruptions||[]).filter(d=>d.status==='Active'),pid=state.settings.planningProject||'',p=state.programmes.find(x=>x.id===pid),legs=state.legs.filter(l=>!pid||l.programmeId===pid),bookings=state.bookings.filter(b=>!pid||b.programmeId===pid),cost=pid?programmeCost(state,pid):portfolioCost(state),late=bookings.filter(b=>b.lateHours>0).length;return pageHead('Test Planning',pid?`Project planning for ${p?.project} inside the shared laboratory capacity plan`:'Automatic resource-constrained portfolio plan with project-specific controls',`<button class="btn" data-act="report-issue">＋ Log Delay / Issue</button><button class="btn" data-act="scenario">◈ What-if</button><button class="btn primary" data-act="update-plan">↻ Update Plan Now</button>`)+
 `<div class="project-plan-bar card"><label>Planning view<select id="planningProject"><option value="">All projects / programmes</option>${state.programmes.map(x=>`<option value="${x.id}" ${pid===x.id?'selected':''}>${x.id} · ${esc(x.project)}</option>`).join('')}</select></label><div class="project-plan-meta">${pid?`<strong>${p.id} · ${esc(p.project)}</strong><span>${p.priority} · due ${fmtDate(p.dueDate)} · ${p.scheduleRisk||p.status}</span>`:'<strong>Portfolio laboratory plan</strong><span>All projects compete for the same qualified resources and equipment</span>'}</div><div class="actions">${pid?`<button class="btn" data-act="project-controls" data-id="${pid}">⚙ Project Controls</button>`:''}<button class="btn" data-act="jump-builder">＋ New Programme</button></div></div>`+
 `<div class="planning-summary"><span class="metric-chip"><b>${legs.filter(l=>l.plannedStart).length}</b> scheduled in view</span><span class="metric-chip"><b>${legs.filter(l=>l.status!=='Completed'&&!l.plannedStart).length}</b> unscheduled</span><span class="metric-chip"><b>${late}</b> late bookings</span><span class="metric-chip"><b>${pid?currency(state,cost.forecast,true):currency(state,cost.totalForecast,true)}</b> forecast cost</span><span class="metric-chip ${state.settings.planDirty?'attention':''}"><b>${active.filter(d=>!pid||d.programmeId===pid).length}</b> active events ${state.settings.planDirty?'· plan refresh needed':''}</span>${state.settings.scenario?`<span class="metric-chip">Scenario: <b>${esc(state.settings.scenario.label||state.settings.scenario.type)}</b> <button class="btn small" data-act="reset-scenario">Reset</button></span>`:''}</div>`+
 `${pid?`<div class="grid section-grid equal">${section('Project readiness',programmeReadiness(pid).checks.map(x=>`<div class="checkline"><span class="${x.ok?'diag-pass':'diag-fail'}">${x.ok?'PASS':'CHECK'}</span><strong>${esc(x.name)}</strong><span class="small muted">${esc(x.detail)}</span></div>`).join(''),`${programmeReadiness(pid).score}% operational readiness`)}${section('Project cost position',costMixViz(programmeCost(state,pid).estimated)+`<div class="callout ${programmeCost(state,pid).variance>0?'danger':''}"><strong>Budget:</strong> ${currency(state,programmeCost(state,pid).budget,true)} · forecast ${currency(state,programmeCost(state,pid).forecast,true)} · variance ${currency(state,programmeCost(state,pid).variance,true)}</div>`,'Same cost engine used in programme builder and execution')}</div>`:''}`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Live planning inputs',activeDisruptionRows(),'Sample delays, test issues and equipment events are hard planning inputs')}${section('Priority strategy scenarios',`<div class="field" style="padding:0 14px"><label>Focus-project scenario</label><select id="scenarioFocus">${state.programmes.map(x=>`<option value="${x.id}" ${state.settings.scenarioFocusProgramme===x.id?'selected':''}>${x.id} · ${esc(x.project)}</option>`).join('')}</select></div>${scenarioCards()}`,'Compare alternative project prioritisation before applying')}</div>`+
 `<div style="margin-top:14px">${section(pid?'Selected project plan inputs':'Portfolio project/leg planning inputs',renderProjectPlanRows(pid),pid?'Edit sample readiness, staff assignment policy and leg due dates':'Select a project above for detailed project-level changes')}</div>`+
 `<div style="margin-top:14px">${section(`Equipment timeline · next 14 days${pid?` · ${p.id}`:''}`,planningTimeline(),'Click a booking to inspect or manually lock/move it')}</div>`+
 `<div style="margin-top:14px">${section('Staff planning view',planningStaffRows(),'Qualified attended bookings in the next 14 days')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Unscheduled / blocked demand',unscheduledRows())}${section('Last replanning impact',planMoveRows())}</div>`;}

function activeDisruptionRows(){const pid=state.settings.planningProject||'';const rows=(state.disruptions||[]).filter(d=>d.status==='Active'&&(!pid||d.programmeId===pid)).sort((a,b)=>new Date(a.effectiveUntil)-new Date(b.effectiveUntil));if(!rows.length)return'<div class="empty">No active operational events. The plan is using normal sample and resource availability.</div>';return `<div class="table-wrap"><table><thead><tr><th>Event</th><th>Programme / Leg</th><th>Constraint until</th><th>Impact</th><th>Action</th></tr></thead><tbody>${rows.map(d=>`<tr><td><strong>${d.id}</strong><div class="small muted">${esc(d.type.replaceAll('_',' '))}</div><div>${esc(d.reason)}</div></td><td>${d.programmeId||'—'}<div class="small muted">${d.legId||d.equipmentId||'programme-level'}</div></td><td>${fmtDate(d.effectiveUntil,true)}</td><td>${Math.round((d.impactHours||0)/24*10)/10} days</td><td><button class="btn small" data-act="resolve-disruption" data-id="${d.id}">Resolve</button></td></tr>`).join('')}</tbody></table></div>`}

function planningTimeline(){const pid=state.settings.planningProject||'';const days=Array.from({length:14},(_,i)=>new Date(DEMO_NOW.getTime()+i*86400000));const viewBookings=state.bookings.filter(b=>!pid||b.programmeId===pid);const eqRows=state.equipment.filter(e=>viewBookings.some(b=>b.equipmentId===e.id)||(!pid&&state.maintenance.some(m=>m.equipmentId===e.id))).slice(0,18);const header=`<div class="gantt-head"><div>Equipment</div>${days.map(d=>`<div>${d.toLocaleDateString(undefined,{weekday:'short',day:'numeric'})}</div>`).join('')}</div>`;const rows=eqRows.map(eq=>{const blocks=[];for(const b of viewBookings.filter(x=>x.equipmentId===eq.id)){const a=(new Date(b.start)-DEMO_NOW)/86400000,z=(new Date(b.end)-new Date(b.start))/86400000;if(a<14&&a+z>0)blocks.push(`<div class="booking ${b.lateHours>0?'late':''} ${b.locked?'locked':''}" data-booking="${b.id}" style="left:calc(180px + ${Math.max(0,a)} * ((100% - 180px)/14));width:calc(${Math.max(.08,Math.min(14-a,z))} * ((100% - 180px)/14))" title="${b.id}">${b.legId} · ${b.programmeId}</div>`)}for(const x of state.maintenance.filter(m=>!pid&&m.equipmentId===eq.id)){const a=(new Date(x.start)-DEMO_NOW)/86400000,z=(new Date(x.end)-new Date(x.start))/86400000;if(a<14&&a+z>0)blocks.push(`<div class="booking maint" style="left:calc(180px + ${Math.max(0,a)} * ((100% - 180px)/14));width:calc(${Math.max(.08,Math.min(14-a,z))} * ((100% - 180px)/14))">${esc(x.type)}</div>`)}return `<div class="gantt-row"><div class="gantt-label"><span class="link" data-entity="equipment" data-id="${eq.id}">${eq.id}</span>&nbsp;${esc(eq.name)}</div>${days.map(()=>'<div class="gantt-cell"></div>').join('')}${blocks.join('')}</div>`}).join('');return `<div class="timeline-legend" style="padding:9px 14px"><span><i class="legend-box"></i> planned</span><span><i class="legend-box late"></i> late</span><span><i class="legend-box maint"></i> maintenance / outage</span><span>▣ outline = locked</span></div><div class="gantt-shell"><div class="gantt">${header}${rows}</div></div>`}
function planningStaffRows(){const pid=state.settings.planningProject||'',end=new Date(DEMO_NOW.getTime()+14*86400000),rows=state.staff.map(s=>{const bs=state.bookings.filter(b=>(!pid||b.programmeId===pid)&&b.staffId===s.id&&new Date(b.start)<end&&new Date(b.staffEnd||b.end)>DEMO_NOW).sort((a,b)=>new Date(a.start)-new Date(b.start));const hours=bs.reduce((sum,b)=>sum+(new Date(b.staffEnd||b.end)-new Date(b.start))/3600000,0);return {s,bs,hours}}).filter(x=>x.bs.length).sort((a,b)=>b.hours-a.hours);return `<div class="table-wrap"><table><thead><tr><th>Staff</th><th>Role</th><th>Booked attended hours</th><th>Upcoming allocations</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="link" data-entity="staff" data-id="${x.s.id}">${esc(x.s.name)}</span></td><td>${esc(x.s.role)}</td><td>${x.hours.toFixed(1)}h</td><td>${x.bs.map(b=>`${b.legId} · ${fmtDate(b.start,true)}`).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`}
function unscheduledRows(){const pid=state.settings.planningProject||'';const ls=state.legs.filter(l=>(!pid||l.programmeId===pid)&&l.status!=='Completed'&&!l.plannedStart);return `<div class="list">${ls.slice(0,12).map(l=>`<div class="list-row"><div><strong><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span> · ${esc(l.name)}</strong><small>${l.programmeId} · due ${fmtDate(l.dueDate)} · ${esc(l.blockingReason||'Awaiting feasible slot')}</small></div>${pill(l.status)}</div>`).join('')||'<div class="empty">All active test demand is scheduled.</div>'}</div>`}
function planMoveRows(){const pid=state.settings.planningProject||'';const moved=(lastPlanDiagnostics?.moved||[]).filter(x=>!pid||state.legs.find(l=>l.id===x.legId)?.programmeId===pid);return `<div class="list">${moved.slice(0,10).map(x=>`<div class="list-row"><div><strong>${x.legId}</strong><small>${fmtDate(x.oldStart,true)} → ${fmtDate(x.newStart,true)} · ${x.oldEquipment||'—'} → ${x.newEquipment||'—'}</small></div>${pill('Rescheduled')}</div>`).join('')||'<div class="empty">No schedule moves recorded in the latest recalculation.</div>'}</div>`}

function renderExecution(){const legs=state.legs.slice().sort((a,b)=>{const order={"In Progress":0,"At Risk":1,"Planned":2,"Blocked":3,"Completed":4,"Draft":5};return (order[a.status]??9)-(order[b.status]??9)});return pageHead('Test Execution','Lifecycle control, release gates, readiness, cost, results and deterministic acceptance evaluation')+`<div class="grid kpi">${kpiCard('In progress',legs.filter(l=>l.status==='In Progress').length,'Active executions')}${kpiCard('Ready / planned',legs.filter(l=>['Ready','Planned'].includes(l.status)).length,'Awaiting start')}${kpiCard('Blocked',legs.filter(l=>l.blockingReason).length,'Constraint or prerequisite')}${kpiCard('Completed',legs.filter(l=>l.status==='Completed').length,'Evidence captured')}${kpiCard('Failed DUTs',state.duts.filter(d=>d.status==='Failed').length,'Derived from results')}${kpiCard('Awaiting review',legs.filter(l=>l.status==='Awaiting Review').length,'Quality review queue')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Leg</th><th>Programme</th><th>Method state</th><th>DUTs</th><th>Planned</th><th>Resources</th><th>Forecast cost</th><th>Status</th><th>Blocking / Evidence</th><th>Action</th></tr></thead><tbody>${legs.map(l=>{const m=state.methods.find(x=>x.id===l.methodId),res=state.results.filter(r=>r.legId===l.id),C=estimateLegCost(state,l);return `<tr><td><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span><div class="muted small">${esc(l.name)}</div></td><td>${l.programmeId}</td><td>${m?.id} Rev ${m?.revision}<div class="muted small">${m?.active?'Released / existing':l.developmentTaskId?`Development ${l.developmentTaskId}`:'Development required'}</div></td><td>${l.dutIds.length}</td><td>${fmtDate(l.plannedStart,true)}<div class="muted small">→ ${fmtDate(l.plannedEnd,true)}</div></td><td>${l.equipmentId||'—'}<div class="muted small">${state.staff.find(s=>s.id===l.staffId)?.name||'—'}</div></td><td><strong>${currency(state,C.total,true)}</strong><div class="muted small">L ${currency(state,C.labour,true)} · E ${currency(state,C.equipment,true)}</div></td><td>${pill(l.status)}</td><td><span class="small">${esc(l.blockingReason||`${res.length} result records`)}</span></td><td>${l.status==='In Progress'?`<button class="btn small primary" data-act="record-result" data-id="${l.id}">Results</button>`:`<button class="btn small" data-act="readiness" data-id="${l.id}">Check</button>`}</td></tr>`}).join('')}</tbody></table></div></section>`}
function renderDUTs(){return pageHead('DUTs & Specimens','Genealogy, programme allocation, failed/removed units and complete test journey')+`<div class="filters"><select id="dutProg"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select><select id="dutStatus"><option value="">All status</option><option>Available</option><option>Failed</option><option>Removed</option></select><input id="dutFilter" placeholder="Serial number or DUT ID"></div><section class="card"><div class="table-wrap"><table><thead><tr><th>DUT</th><th>Serial</th><th>Product</th><th>Programme</th><th>Group</th><th>Status</th><th>Legs assigned</th><th>Results</th></tr></thead><tbody id="dutBody"></tbody></table></div></section>`}
function renderDutTable(){const pr=document.getElementById('dutProg')?.value||'',st=document.getElementById('dutStatus')?.value||'',f=(document.getElementById('dutFilter')?.value||'').toLowerCase();const rows=state.duts.filter(d=>(!pr||d.programmeId===pr)&&(!st||d.status===st)&&(!f||`${d.id} ${d.serialNumber}`.toLowerCase().includes(f)));document.getElementById('dutBody').innerHTML=rows.map(d=>{const ls=state.legs.filter(l=>l.dutIds.includes(d.id)),rs=state.results.filter(r=>r.dutId===d.id);return `<tr><td><span class="link mono" data-entity="dut" data-id="${d.id}">${d.id}</span></td><td>${d.serialNumber}</td><td>${esc(d.product)}</td><td>${d.programmeId}</td><td>${d.group}</td><td>${pill(d.status)}</td><td>${ls.length}</td><td>${rs.length} · ${rs.some(r=>r.status==='FAIL')?pill('FAIL'):rs.length?pill('PASS'):'—'}</td></tr>`}).join('');wireEntities(document.getElementById('dutBody'));}

function renderLibrary(){const methods=state.methods,devOpen=state.devTasks.filter(d=>!d.completeDate);return pageHead('Test Library','Released methods, development demand, standard cost, competency coverage and evidence-based lessons learned',`<button class="btn" data-act="request-new-test">＋ Request New Test</button><button class="btn primary" data-act="jump-builder">＋ Build Programme</button>`)+`<div class="grid kpi">${kpiCard('Released methods',methods.filter(m=>m.active).length,'Immediately selectable for released programmes')}${kpiCard('Needs development',methods.filter(m=>!m.active).length,`${devOpen.length} open development tasks`)}${kpiCard('Standard execution',state.legs.filter(l=>!l.developmentTaskId).length,'Legs using released methods')}${kpiCard('Avg actual variance',`${Math.round(methods.reduce((s,m)=>s+(m.avgActualFactor-1),0)/Math.max(1,methods.length)*100)}%`,'Actual vs library standard')}${kpiCard('Single-person methods',methods.filter(m=>methodLessons(m.id).qualified===1).length,'Competency continuity risk')}${kpiCard('Historical issues',(state.issues||[]).length,'Feeds programme-builder recommendations')}</div><section class="card"><div class="section-title"><h2>Controlled Test Method Library</h2><span class="hint">Cost shown for a representative 8-DUT leg</span></div><div class="table-wrap"><table><thead><tr><th>Method</th><th>State</th><th>Category / Rev</th><th>Standard duration</th><th>Resource / Skill</th><th>Capacity</th><th>Typical cost</th><th>History</th><th>Competency</th><th>Lessons signal</th></tr></thead><tbody>${methods.map(m=>{const L=methodLessons(m.id),C=methodCost(state,m.id,8),dev=state.devTasks.filter(d=>!d.completeDate&&state.legs.some(l=>l.developmentTaskId===d.id&&l.methodId===m.id));return `<tr><td><span class="link mono" data-entity="method" data-id="${m.id}">${m.id}</span><div><strong>${esc(m.name)}</strong></div></td><td>${pill(m.active?'Exists / Released':'Needs Development')}<div class="muted small">${dev.length?dev.map(x=>x.id).join(', '):m.active?'Reusable standard':'No released method'}</div></td><td>${m.category}<div class="muted small">Rev ${m.revision}</div></td><td>${m.setupHours+m.executionHours+m.teardownHours+m.analysisHours}h<div class="muted small">setup ${m.setupHours} · run ${m.executionHours} · teardown ${m.teardownHours} · analysis ${m.analysisHours}</div></td><td>${m.equipmentType}<div class="muted small">${m.requiredSkills.join(', ')}</div></td><td>${m.dutCapacity} DUTs</td><td><strong>${currency(state,C.total,true)}</strong><div class="muted small">8-DUT planning estimate</div></td><td>${L.runs} runs<div class="muted small">${L.issues} issues · ${L.delayHours}h delay · ${L.durationVariance>=0?'+':''}${L.durationVariance}% duration</div></td><td><strong>${L.qualified}</strong><div class="muted small">independent+ qualified</div></td><td><span class="small">${esc(L.recommendation)}</span></td></tr>`}).join('')}</tbody></table></div></section>`}
function renderEquipment(){const u=resourceUtilisation(state),map=Object.fromEntries(u.equipment.map(x=>[x.id,x]));return pageHead('Equipment Register','Capability, utilisation, calibration, maintenance and planning availability',`<button class="btn" data-act="export-equipment-csv">⇩ Equipment CSV</button>`)+`<div class="grid kpi">${kpiCard('Assets',state.equipment.length,'Registered laboratory equipment')}${kpiCard('Available',state.equipment.filter(e=>e.status==='Available').length,'Current asset status')}${kpiCard('Maintenance',state.equipment.filter(e=>e.status==='Maintenance').length,'Unavailable by status')}${kpiCard('Breakdown',state.equipment.filter(e=>e.status==='Breakdown').length,'Corrective maintenance')}${kpiCard('Calibration risk',state.equipment.filter(e=>['red','amber'].includes(calibrationStatus(e,state).tone)).length,'Expired or due ≤60d')}${kpiCard('Portfolio utilisation',`${u.equipmentAvg}%`,'Next 4 weeks')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Type / Capability</th><th>Manufacturer</th><th>Location</th><th>Status</th><th>Capacity</th><th>Utilisation</th><th>Calibration</th><th>Maintenance</th></tr></thead><tbody>${state.equipment.map(e=>{const c=calibrationStatus(e,state),ut=map[e.id]?.pct||0;return `<tr><td><span class="link mono" data-entity="equipment" data-id="${e.id}">${e.id}</span><div class="muted small">${e.assetNumber} · ${e.serialNumber}</div></td><td><strong>${esc(e.name)}</strong><div class="muted small">${esc(e.capability)}</div></td><td>${e.manufacturer}<div class="muted small">${e.model}</div></td><td>${e.location}</td><td>${pill(e.status)}</td><td>${e.capacity}</td><td><div class="bar-head"><span>${ut}%</span></div><div class="heat"><span style="width:${ut}%"></span></div></td><td><span class="pill ${c.tone}">${c.label}</span><div class="muted small">${fmtDate(e.calibrationDue)}</div></td><td>${fmtDate(e.maintenanceDate)}</td></tr>`}).join('')}</tbody></table></div></section>`}

function renderCalibration(){const current=state.equipment.filter(e=>e.calibrationRequired).map(e=>{const s=calibrationStatus(e,state),c=s.calibration,next=nextScheduledCalibration(state,e.id);return{e,c,next,s}}).sort((a,b)=>(a.s.days??999)-(b.s.days??999));const affected=state.bookings.filter(b=>{const e=state.equipment.find(x=>x.id===b.equipmentId);if(!e?.calibrationRequired)return false;const c=calibrationAt(state,e.id,b.start,{allowScheduled:true});return !c||new Date(c.dueDate)<new Date(b.end)}).length;return pageHead('Calibration Management','Validity, warning horizons, certificates and planning impact',`<button class="btn" data-act="add-calibration">＋ Add Calibration</button><button class="btn" data-act="export-cal-csv">⇩ CSV</button>`)+`<div class="grid kpi">${kpiCard('Valid',current.filter(x=>x.s.tone==='green').length,'Beyond 60-day warning')}${kpiCard('Due ≤60d',current.filter(x=>x.s.tone==='amber').length,'Amber warning')}${kpiCard('Expired / ≤7d',current.filter(x=>x.s.tone==='red').length,'Planning blocker / urgent')}${kpiCard('Calibration records',state.calibrations.length,'Current, historical + scheduled')}${kpiCard('Future tests affected',affected,'Effective calibration checked at planned use')}${kpiCard('Warning thresholds',state.settings.calibrationWarningDays.join(' / ')+'d','Configurable in Administration')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Equipment</th><th>Current calibration</th><th>Date</th><th>Due</th><th>Status</th><th>Next planned</th><th>Provider</th><th>Certificate</th><th>As found / left</th></tr></thead><tbody>${current.map(x=>`<tr><td><span class="link mono" data-entity="equipment" data-id="${x.e.id}">${x.e.id}</span><div>${esc(x.e.name)}</div></td><td class="mono">${x.c?.id||'—'}</td><td>${fmtDate(x.c?.calibrationDate)}</td><td>${fmtDate(x.c?.dueDate)}</td><td><span class="pill ${x.s.tone}">${x.s.label}</span></td><td>${x.next?`<span class="pill blue">Scheduled</span><div class="muted small">${fmtDate(x.next.calibrationDate,true)} · ${esc(x.next.id)}</div>`:'—'}</td><td>${esc(x.c?.provider||'—')}</td><td>${x.c?`<a class="link" href="${esc(x.c.certificatePath)}" target="_blank" rel="noopener">${esc(x.c.certificateNumber)}</a>`:'—'}</td><td>${esc(x.c?.asFound||'—')} / ${esc(x.c?.asLeft||'—')}</td></tr>`).join('')}</tbody></table></div></section>`}

function renderPeople(){const u=resourceUtilisation(state),um=Object.fromEntries(u.staff.map(x=>[x.id,x])),risks=skillsRisks(state);return pageHead('People & Skills','Competency, authorisation, availability, workload and single-point qualification risks')+`<div class="grid kpi">${kpiCard('Staff',state.staff.length,'Technicians, engineers, specialists, manager')}${kpiCard('Staff utilisation',`${u.staffAvg}%`,'Attended planning load')}${kpiCard('Single-point skills',risks.filter(r=>r.count===1).length,'Only one independent operator')}${kpiCard('Qualification gaps',risks.filter(r=>r.count===0).length,'No independent coverage')}${kpiCard('Methods covered',`${pct(state.methods.length-risks.filter(r=>r.count===0).length,state.methods.length)}%`,'At least one independent qualification')}${kpiCard('People unavailable',state.staff.filter(s=>s.availability.some(a=>new Date(a.end)>DEMO_NOW)).length,'Future leave / training blocks')}</div><div class="grid section-grid"><section class="card"><div class="section-title"><h2>Staff workload</h2></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Role / Team</th><th>Skills</th><th>Qualifications</th><th>Availability</th><th>Workload</th></tr></thead><tbody>${state.staff.map(s=>{const ut=um[s.id]?.pct||0;return `<tr><td><span class="link" data-entity="staff" data-id="${s.id}">${esc(s.name)}</span><div class="mono small muted">${s.id}</div></td><td>${esc(s.role)}<div class="muted small">${esc(s.team)}</div></td><td>${s.skills.join(', ')}</td><td>${s.qualifications.length}<div class="muted small">${s.proficiency}</div></td><td>${s.availability.map(a=>`${fmtDate(a.start)}–${fmtDate(a.end)} ${a.reason}`).join('<br>')||'Available'}</td><td>${ut}%<div class="heat"><span style="width:${ut}%"></span></div></td></tr>`}).join('')}</tbody></table></div></section>${section('Single-point competency risks',risks.slice(0,15).map(r=>`<div class="list-row"><div><strong>${r.methodId} · ${esc(r.name)}</strong><small>${r.count?esc(r.people):'No independent qualified person'}</small></div><span class="pill ${r.count===0?'red':'amber'}">${r.count} qualified</span></div>`).join('')||'<div class="empty">No coverage risks.</div>','Independent / Reviewer / Expert levels')}</div>`}

function renderAnalytics(){const p=periodRange(),PM=periodMetrics(state,p.start,p.end),TR=periodTrend(state,p.start,p.end),IA=issueAnalytics(state,p.start,p.end);const cats={};for(const r of PM.runs){const m=state.methods.find(x=>x.id===r.methodId),c=m?.category||'Other';cats[c]=cats[c]||{name:c,count:0,actual:0,standard:0,fail:0};cats[c].count++;cats[c].actual+=Number(r.actualHours)||0;cats[c].standard+=Number(r.standardHours)||0;if(r.outcome==='FAIL')cats[c].fail++;}const catRows=Object.values(cats).sort((a,b)=>b.count-a.count);const meth={};for(const r of PM.runs){const m=state.methods.find(x=>x.id===r.methodId);meth[r.methodId]=meth[r.methodId]||{id:r.methodId,name:m?.name||r.methodId,count:0,actual:0,standard:0};const x=meth[r.methodId];x.count++;x.actual+=Number(r.actualHours)||0;x.standard+=Number(r.standardHours)||0;}const methodRows=Object.values(meth).map(x=>({...x,variance:Math.round((x.actual-x.standard)/Math.max(1,x.standard)*100)})).sort((a,b)=>Math.abs(b.variance)-Math.abs(a.variance)).slice(0,12);return pageHead('Reports / Analytics','Period-selectable laboratory performance, issue Pareto, lessons learned, utilisation and planned-vs-actual insight',`<button class="btn" data-act="export-plan-csv">⇩ Test Plan CSV</button><button class="btn" data-act="export-kpi-csv">⇩ KPI CSV</button>`)+periodControls()+
 `<div class="grid kpi visual-kpis">${kpiCard('Completed',PM.completed,periodLabel())}${kpiCard('On-time',`${PM.onTimePct}%`,'Actual end ≤ planned end')}${kpiCard('Pass rate',`${PM.passRate}%`,`${PM.failed} fail · ${PM.rework} rework`)}${kpiCard('Avg turnaround',`${PM.avgTurnaround}h`, `median ${PM.medianTurnaround}h`)}${kpiCard('Actual vs standard',`${PM.durationVariancePct>=0?'+':''}${PM.durationVariancePct}%`,`${PM.actualHours}h actual · ${PM.standardHours}h standard`)}${kpiCard('Issue delay',`${PM.issueDelayHours}h`,`${PM.issues} issue records`)}</div>`+
 `<div class="grid section-grid equal">${section('Throughput & issue trend',trendViz(TR),`${TR.mode} buckets · selected KPI period`)}${section('Outcome mix & issue root causes',outcomeViz(PM)+rootCauseDonut(IA.rootCauses),'Spec vs execution vs sample/equipment causes')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Issue Pareto — highest occurrence',horizontalViz(IA.topTypes.slice(0,10)),'Occurrence first; delay hours shown alongside')}${section('Execution vs bad specification',`<div class="cause-compare"><div><strong>Test execution</strong><b>${IA.testExecution}</b><span>${Math.round(IA.testExecution/Math.max(1,IA.total)*100)}% of issues</span><div class="viz-track"><i style="width:${IA.testExecution/Math.max(1,IA.total)*100}%"></i></div></div><div><strong>Bad / ambiguous specifications</strong><b>${IA.badSpecification}</b><span>${Math.round(IA.badSpecification/Math.max(1,IA.total)*100)}% of issues</span><div class="viz-track spec"><i style="width:${IA.badSpecification/Math.max(1,IA.total)*100}%"></i></div></div></div>${horizontalViz(IA.rootCauses.slice(0,7))}`,'Root cause is stored per issue and aggregated automatically')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Automatic lessons learned',IA.lessons.map(x=>`<div class="lesson-row"><span class="lesson-rank">${x.rank}</span><div><strong>${esc(x.issue)}</strong><small>${x.occurrences} occurrences · ${x.share}% of period issues · ${x.delayHours}h delay</small><p>${esc(x.lesson)}</p></div>${pill(x.priority)}</div>`).join('')||'<div class="empty">No issue history in the selected period.</div>','Ranked by recurrence and delay impact')}${section('Category throughput',horizontalViz(catRows.map(x=>({name:x.name,count:x.count,delayHours:Math.max(0,Math.round((x.actual-x.standard)*10)/10)})).slice(0,12)),'Tests completed; variance hours shown as context')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Equipment utilisation',horizontalViz(PM.equipment.slice().sort((a,b)=>b.pct-a.pct).slice(0,12),'pct','%'),'Actual runs + future bookings inside selected period')}${section('Staff utilisation',horizontalViz(PM.staff.slice().sort((a,b)=>b.pct-a.pct).slice(0,12),'pct','%'),'Attended workload versus available working hours')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Programme cost outlook',horizontalViz(portfolioCost(state).programmes.sort((a,b)=>b.forecast-a.forecast).slice(0,10).map(x=>({name:`${x.programmeId} · ${state.programmes.find(p=>p.id===x.programmeId)?.project||''}`,count:Math.round(x.forecast/1000),delayHours:Math.round(x.variance/1000)})),'count','k'),'Forecast €k; secondary value is variance €k')}${section('Cost mix',costMixViz(portfolioCost(state).breakdown),'Labour, equipment, consumables, development and overhead')}</div>`+
 `<div style="margin-top:14px">${section('Methods whose actual duration differs most from library standard',`<div class="table-wrap"><table><thead><tr><th>Method</th><th>Runs</th><th>Standard hours</th><th>Actual hours</th><th>Variance</th><th>Recommendation</th></tr></thead><tbody>${methodRows.map(x=>`<tr><td><strong>${x.id}</strong><div class="small muted">${esc(x.name)}</div></td><td>${x.count}</td><td>${Math.round(x.standard*10)/10}</td><td>${Math.round(x.actual*10)/10}</td><td><span class="pill ${Math.abs(x.variance)>=15?'amber':'green'}">${x.variance>=0?'+':''}${x.variance}%</span></td><td>${x.variance>15?'Review library duration / recurrent delay cause':x.variance<-15?'Consider reducing standard duration after sufficient evidence':'Standard duration remains representative'}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No completed runs in this period.</div></td></tr>'}</tbody></table></div>`,'Planned-vs-actual feedback loop into the Test Library')}</div>`;}

function renderAdmin(){const d=runDiagnostics(state);const examples=[['LabOS-Test-Programme-Template.pdf','Test programme template'],['LabOS-Cost-Framework-Guide.pdf','Cost framework guide'],['LabOS-Sample-Test-Report.pdf','Completed test report example'],['LabOS-Method-Development-Plan.pdf','New-method development plan'],['LabOS-Cost-Rate-Card.csv','Editable example rate card'],['LabOS-Test-Programme-Template.csv','Programme import/build example'],['LabOS-Requirements-Import-Template.csv','Requirements import / coverage example'],['LabOS-Specification-Review-Checklist.csv','Specification release checklist']];return pageHead('Administration / Demo','Persistence, example artefacts, scenarios, audit history and deterministic system verification')+`<div class="grid section-grid equal"><section class="card pad"><h2 style="margin-top:0">Demo & Data</h2><div class="detail-grid"><div class="detail"><small>Version</small><strong>LabOS Prototype v${APP_VERSION}</strong></div><div class="detail"><small>Persistence</small><strong>IndexedDB + fallback</strong></div><div class="detail"><small>Demo actor</small><strong>${esc(state.settings.actor)}</strong></div></div><div class="actions"><button class="btn" data-act="export-json">⇩ Export Data</button><button class="btn" data-act="import-json">⇧ Import Data</button><button class="btn danger" data-act="reset-demo">↺ Reset Demo Data</button></div><div class="field"><label>Demo actor</label><input id="actorInput" value="${esc(state.settings.actor)}"></div><button class="btn small" data-act="save-actor">Save actor</button><p class="small muted">Prototype audit history is browser-local and is not a validated electronic-signature or production audit system.</p></section>${section('System Data Integrity',`<div class="callout ${d.overall==='PASS'?'':'danger'}"><strong>${d.overall}</strong> · ${d.pass}/${d.checks.length} automated checks passing.</div><div class="list">${d.checks.map(c=>`<div class="checkline"><span class="${c.ok?'diag-pass':'diag-fail'}">${c.ok?'PASS':'FAIL'}</span><strong>${esc(c.name)}</strong><span class="small muted">${esc(c.detail)}</span></div>`).join('')}</div><div style="padding:12px"><button class="btn primary" data-act="verify">✓ Run System Verification</button></div>`,'Verification uses current canonical browser data')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Operational example files',examples.map(([f,n])=>`<a class="doc-tile" href="${f}" target="_blank" rel="noopener"><div class="doc-icon">${f.endsWith('.pdf')?'PDF':'CSV'}</div><div><strong>${esc(n)}</strong><small>${f}</small></div></a>`).join(''),'Included in the flat GitHub package; no external services required')}${section('What-if scenario',scenarioPanel())}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Calibration warning thresholds',`<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Warning days (comma separated)</label><input id="calWarn" value="${state.settings.calibrationWarningDays.join(', ')}"></div><button class="btn small" data-act="save-warnings">Save thresholds</button><p class="small muted">Current visual bands use urgent ≤7d, warning ≤60d. Thresholds are retained for future policy expansion.</p></div>`)}${section('Prototype control boundaries',`<div class="list"><div class="list-row"><div><strong>Operational controls represented</strong><small>Release gates · competency · calibration · sample readiness · resource conflicts · cost · audit · evidence</small></div>${pill('Demo')}</div><div class="list-row"><div><strong>Production controls intentionally excluded</strong><small>Authentication · electronic signatures · central DB · server security · concurrent edits · authoritative backup</small></div>${pill('Not production')}</div></div>`)}</div>${section('Audit History',`<div class="audit list">${state.audit.slice().reverse().slice(0,40).map(a=>`<div class="list-row"><span>${fmtDate(a.timestamp,true)}</span><strong>${esc(a.actor)}</strong><div><b>${esc(a.action)}</b> · ${esc(a.entity)}<small>${esc(a.previousValue)} ${a.previousValue||a.newValue?'→':''} ${esc(a.newValue)}</small></div></div>`).join('')}</div>`,'Latest 40 session/demo events')}`}
function reportIssueModal(){const activeLegs=state.legs.filter(l=>!['Completed','Cancelled','Failed'].includes(l.status));openModal(`<h2>Log Delay / Test Issue</h2><div class="modal-grid"><div class="field"><label>Event type</label><select id="issType"><option value="sample_delay">Sample / DUT delay</option><option value="test_issue">Test execution issue</option><option value="equipment_issue">Equipment outage / interruption</option><option value="spec_issue">Bad / ambiguous specification</option><option value="resource_issue">Staff / qualification issue</option></select></div><div class="field"><label>Programme</label><select id="issProg">${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select></div><div class="field"><label>Affected test leg</label><select id="issLeg"><option value="">Programme-level</option>${activeLegs.map(l=>`<option value="${l.id}" data-prog="${l.programmeId}">${l.id} · ${l.programmeId} · ${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Equipment (if applicable)</label><select id="issEq"><option value="">None / not equipment-specific</option>${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Specification (if applicable)</label><select id="issSpec"><option value="">None</option>${state.specifications.map(sp=>`<option value="${sp.id}">${sp.id} Rev ${esc(sp.revision)} · ${esc(sp.name)}</option>`).join('')}</select></div><div class="field"><label>Severity</label><select id="issSeverity"><option>Low</option><option selected>Medium</option><option>High</option><option>Critical</option></select></div><div class="field"><label>Constraint / recovery until</label><input id="issUntil" type="datetime-local" value="${dayISO(3,12).slice(0,16)}"></div><div class="field"><label>Estimated delay impact (hours)</label><input id="issHours" type="number" min="0" step="1" value="24"></div></div><div class="field"><label>Issue description</label><textarea id="issDesc">Sample / test condition changed; planner must account for the new availability constraint.</textarea></div><div class="field"><label>Issue subtype</label><input id="issSubtype" value="Sample arrival delay"></div><div class="callout"><strong>Planning behaviour:</strong> sample delays, test issues, resource issues and equipment interruptions become active planning constraints. Specification issues are recorded for quality/lessons analytics and can be linked to a specific spec.</div><div class="actions" style="margin-top:14px"><button id="saveIssue" class="btn primary">Save Issue</button><button id="saveIssueReplan" class="btn">Save & Update Plan</button></div>`);const sync=()=>{const t=document.getElementById('issType').value,sub=document.getElementById('issSubtype'),desc=document.getElementById('issDesc');const map={sample_delay:['Sample arrival delay','Customer sample/DUT availability changed.'],test_issue:['Fixture / connection problem','Test execution issue requires recovery or repeat work.'],equipment_issue:['Equipment interruption','Equipment is unavailable until recovery.'],spec_issue:['Specification ambiguity','Specification ambiguity or missing acceptance criterion identified.'],resource_issue:['Qualification / staffing gap','Required competent resource is unavailable.']};sub.value=map[t][0];desc.value=map[t][1]};document.getElementById('issType').onchange=sync;const prog=document.getElementById('issProg'),legSel=document.getElementById('issLeg'),specSel=document.getElementById('issSpec');prog.onchange=()=>{for(const o of [...legSel.options])if(o.value)o.hidden=o.dataset.prog!==prog.value;legSel.value='';for(const o of [...specSel.options])if(o.value)o.hidden=state.specifications.find(x=>x.id===o.value)?.programmeId!==prog.value;specSel.value=''};prog.onchange();const save=async(doReplan)=>{const type=document.getElementById('issType').value,pid=prog.value,legId=legSel.value||null,eqId=document.getElementById('issEq').value||null,specId=document.getElementById('issSpec').value||null,severity=document.getElementById('issSeverity').value,untilRaw=document.getElementById('issUntil').value,hours=Math.max(0,Number(document.getElementById('issHours').value)||0),description=document.getElementById('issDesc').value.trim(),issueType=document.getElementById('issSubtype').value.trim()||'Operational issue';if(!description)return toast('Describe the issue.');if(type==='equipment_issue'&&!eqId)return toast('Select the affected equipment for an equipment outage.');if(type!=='spec_issue'&&!untilRaw)return toast('Set the recovery / constraint end time.');const untilDate=untilRaw?new Date(untilRaw):null;if(untilDate&&Number.isNaN(untilDate.getTime()))return toast('Enter a valid recovery time.');const until=untilDate?untilDate.toISOString():null;const rootCause=type==='spec_issue'?'Bad Specification':type==='sample_delay'?'Sample / DUT':type==='equipment_issue'?'Equipment / Facility':type==='resource_issue'?'Planning / Resource':'Test Execution';const lesson=rootCause==='Bad Specification'?'Add a specification completeness/ambiguity gate before test release':rootCause==='Test Execution'?'Standardise pre-test setup checks and capture recurrent execution failure modes':rootCause==='Sample / DUT'?'Make confirmed sample-ready date a hard planning input':'Expose resource interruptions immediately and maintain contingency capacity';const iid=`ISS-${String((state.issues||[]).length+1).padStart(3,'0')}`,issue={id:iid,reportedAt:new Date().toISOString(),programmeId:pid,legId,testRunId:null,specificationId:specId,issueType,rootCause,severity,delayHours:hours,status:'Open',description,lesson,correctiveAction:lesson,owner:state.settings.actor};state.issues.push(issue);let dsp=null;if(type!=='spec_issue'){const dtype=type==='resource_issue'?'test_issue':type;dsp={id:`DSP-${String((state.disruptions||[]).length+1).padStart(3,'0')}`,type:dtype,status:'Active',programmeId:pid,legId:legId,equipmentId:type==='equipment_issue'?eqId:null,reportedAt:new Date().toISOString(),effectiveUntil:until,reason:description,impactHours:hours,sourceIssueId:iid};state.disruptions.push(dsp);state.settings.planDirty=true}if(specId&&rootCause==='Bad Specification'){const sp=state.specifications.find(x=>x.id===specId);if(sp){sp.qualityScore=Math.max(0,(Number(sp.qualityScore)||80)-5);sp.qualityFlags=[...new Set([...(sp.qualityFlags||[]),issueType])]}}state.audit.push(audit('Operational issue logged',iid,'',`${rootCause} · ${hours}h`));if(doReplan){const r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;}await persist();closeModal();render();toast(doReplan?`${iid} saved; laboratory plan updated.`:`${iid} saved. Tap “Update Plan Now” to replan.`)};document.getElementById('saveIssue').onclick=()=>save(false);document.getElementById('saveIssueReplan').onclick=()=>save(true)}
async function resolveDisruption(id){const d=(state.disruptions||[]).find(x=>x.id===id);if(!d)return;d.status='Resolved';d.resolvedAt=new Date().toISOString();const i=(state.issues||[]).find(x=>x.id===d.sourceIssueId);if(i)i.status='Closed';state.settings.planDirty=true;state.audit.push(audit('Planning disruption resolved',id,'Active','Resolved'));await persist();render();toast(`${id} resolved. Update the plan to release the constraint.`)}
async function applyPriorityScenario(strategy){const sc=priorityMaps().find(x=>x.id===strategy);if(!sc||!sc.map)return;const scenario={type:'priority_mix',priorityMap:sc.map,label:sc.name};state.settings.scenario=scenario;state.audit.push(audit('Priority scenario applied','Planning','',sc.name));const r=scheduleAll(state,{scenario});state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`${sc.name} applied; ${r.diagnostics.moved.length} bookings moved.`)}

function scenarioPanel(){return `<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Scenario</label><select id="scenarioType"><option value="equipment_unavailable">Equipment unavailable for 7 days</option><option value="staff_unavailable">Staff unavailable next week</option><option value="add_equipment">Add temporary thermal chamber</option></select></div><div class="field" id="scenarioTargetWrap"><label>Target</label><select id="scenarioTarget">${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="actions"><button class="btn primary" data-act="apply-scenario">Apply & Replan</button>${state.settings.scenario?'<button class="btn" data-act="reset-scenario">Reset Scenario</button>':''}</div>${state.settings.scenario?`<div class="callout warning" style="margin-top:12px"><strong>Active:</strong> ${esc(state.settings.scenario.label||state.settings.scenario.type)}</div>`:''}</div>`}

function wireRoute(){wireEntities(main);for(const b of main.querySelectorAll('[data-act]'))b.addEventListener('click',handleAction);for(const b of main.querySelectorAll('[data-booking]'))b.addEventListener('click',()=>showBooking(b.dataset.booking));if(route==='dashboard'){for(const x of ['dashProgramme','dashCustomer','dashCategory','dashPriority','dashStatus','dashEquipment','dashStaff']){const el=document.getElementById(x);if(el)el.addEventListener('change',async()=>{state.settings.dashboardFilters={programme:document.getElementById('dashProgramme').value,customer:document.getElementById('dashCustomer').value,category:document.getElementById('dashCategory').value,priority:document.getElementById('dashPriority').value,status:document.getElementById('dashStatus').value,equipment:document.getElementById('dashEquipment').value,staff:document.getElementById('dashStaff').value};await persist();render();});}wirePeriodControls()}if(route==='analytics')wirePeriodControls();if(route==='requirements'){for(const x of ['reqProg','reqStatus','reqCrit','reqCategory','reqAttention','reqFilter'])document.getElementById(x)?.addEventListener('input',renderReqTable);renderReqTable()}if(route==='specifications'){for(const x of ['specProg','specStatus','specAttention','specFilter'])document.getElementById(x)?.addEventListener('input',renderSpecTable);renderSpecTable()}if(route==='duts'){for(const x of ['dutProg','dutStatus','dutFilter'])document.getElementById(x).addEventListener('input',renderDutTable);renderDutTable()}if(route==='programmes'){for(const s of main.querySelectorAll('.priority-change'))s.addEventListener('change',()=>changePriority(s.dataset.id,s.value))}if(route==='planning'){const pp=document.getElementById('planningProject');if(pp)pp.onchange=async()=>{state.settings.planningProject=pp.value;await persist();render()};const f=document.getElementById('scenarioFocus');if(f)f.onchange=async()=>{state.settings.scenarioFocusProgramme=f.value;await persist();render()}}if(route==='builder')wireBuilder();if(route==='costs'){const c=document.getElementById('costProgramme');if(c)c.onchange=async()=>{state.settings.costProgramme=c.value;await persist();render()}}if(route==='admin'){const t=document.getElementById('scenarioType');if(t)t.onchange=updateScenarioTargets;updateScenarioTargets();}}

function wireEntities(root){for(const el of root.querySelectorAll('[data-entity]'))el.addEventListener('click',e=>{e.preventDefault();showEntity(el.dataset.entity,el.dataset.id)})}

async function handleAction(e){const b=e.currentTarget,a=b.dataset.act,id=b.dataset.id;if(a==='replan'||a==='update-plan')return replan();if(a==='scenario')return go('admin');if(a==='reset-scenario')return resetScenario();if(a==='readiness')return showReadiness(id);if(a==='export-json')return exportJSON();if(a==='import-json')return document.getElementById('importFile').click();if(a==='reset-demo')return resetDemo();if(a==='verify')return verifyUI();if(a==='export-req-csv')return exportCSV('requirements');if(a==='export-equipment-csv')return exportCSV('equipment');if(a==='export-cal-csv')return exportCSV('calibrations');if(a==='export-plan-csv')return exportCSV('plan');if(a==='export-kpi-csv')return exportCSV('kpis');if(a==='save-actor'){const v=document.getElementById('actorInput').value.trim()||'Demo Lab Manager';state.audit.push(audit('Demo actor changed','Settings',state.settings.actor,v));state.settings.actor=v;await persist();render();return}if(a==='save-warnings'){const v=document.getElementById('calWarn').value.split(',').map(x=>parseInt(x.trim())).filter(x=>Number.isFinite(x)&&x>0).sort((a,b)=>b-a);if(!v.length)return toast('Enter at least one positive warning threshold.');state.settings.calibrationWarningDays=v;state.audit.push(audit('Calibration warning thresholds changed','Settings','',v.join(',')));await persist();render();return}if(a==='apply-scenario')return applyScenario();if(a==='apply-priority-scenario')return applyPriorityScenario(b.dataset.strategy);if(a==='add-calibration')return addCalibrationModal();if(a==='request-new-test')return requestNewTestModal();if(a==='record-result')return recordResultModal(id);if(a==='report-issue')return reportIssueModal();if(a==='resolve-disruption')return resolveDisruption(id);if(a==='upload-spec')return uploadSpecModal();if(a==='open-spec'){const sp=state.specifications.find(x=>x.id===id);return sp?openSpecificationDocument(sp):null;}if(a==='review-spec')return openSpecReviewModal(id);if(a==='impact-spec')return showSpecImpact(id);if(a==='add-requirement')return addRequirementModal();if(a==='cover-requirement')return coverRequirementModal(id);if(a==='jump-builder')return go('builder');if(a==='open-project-plan'){state.settings.planningProject=id;await persist();return go('planning');}if(a==='project-controls')return projectControlsModal(id);if(a==='edit-project-leg')return editProjectLegModal(id);if(a==='cost-settings')return costSettingsModal();if(a==='edit-cost-budget')return editCostBudgetModal(id);if(a==='cost-programme'){state.settings.costProgramme=id;await persist();return render();}if(a==='export-cost-csv')return exportCSV('costs');if(a==='builder-template')return applyBuilderTemplate(id);if(a==='builder-reset')return resetBuilder();if(a==='builder-add-custom')return builderAddCustom();if(a==='builder-remove-custom')return builderRemoveCustom(id);if(a==='builder-create-draft')return createBuilderProgramme(false);if(a==='builder-create-plan')return createBuilderProgramme(true);}

async function replan(){const r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;recomputeRequirementStatuses(state);await persist();render();toast(`Plan updated from current delays/issues: ${r.diagnostics.moved.length} moved, ${r.diagnostics.unscheduled.length} unscheduled.`)}
async function changePriority(id,val){state=applyPriority(state,id,val);const r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`${id} set to ${val}; ${r.diagnostics.moved.length} bookings moved.`)}
function updateScenarioTargets(){const t=document.getElementById('scenarioType'),sel=document.getElementById('scenarioTarget');if(!t||!sel)return;if(t.value==='staff_unavailable')sel.innerHTML=state.staff.map(s=>`<option value="${s.id}">${s.id} · ${esc(s.name)}</option>`).join('');else if(t.value==='add_equipment')sel.innerHTML=[...new Set(state.equipment.map(e=>e.type))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');else sel.innerHTML=state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}
async function applyScenario(){const type=document.getElementById('scenarioType').value,target=document.getElementById('scenarioTarget').value;let sc;if(type==='equipment_unavailable')sc={type,equipmentId:target,start:dayISO(0,8),end:dayISO(7,17),label:`${target} unavailable for 7 days`};else if(type==='staff_unavailable')sc={type,staffId:target,start:dayISO(3,8),end:dayISO(10,17),label:`${state.staff.find(s=>s.id===target)?.name} unavailable next week`};else sc={type,equipmentType:target,label:`Add temporary ${target}`};state.settings.scenario=sc;state.audit.push(audit('Scenario applied','Planning','',sc.label));const r=scheduleAll(state,{scenario:sc});state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`Scenario applied; ${r.diagnostics.moved.length} bookings moved.`)}
async function resetScenario(){state.settings.scenario=null;state.audit.push(audit('Scenario reset','Planning','active','baseline'));const r=scheduleAll(state,{scenario:null});state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast('Scenario reset and baseline schedule recalculated.');}

function showEntity(type,id){if(type==='requirement')return showRequirement(id);if(type==='specification')return showSpecification(id);if(type==='programme')return showProgramme(id);if(type==='leg')return showLeg(id);if(type==='dut')return showDut(id);if(type==='equipment')return showEquipmentDetail(id);if(type==='method')return showMethod(id);if(type==='staff')return showStaff(id)}
function showRequirement(id){const r=state.requirements.find(x=>x.id===id);if(!r)return;const o=requirementOps(r),results=o.results,methods=o.methods.length?o.methods:[o.suggested].filter(Boolean);openModal(`<h2>${r.id} · Requirement Decision & Traceability</h2><div class="callout"><strong>${esc(r.text)}</strong><div class="small">Acceptance criterion: ${esc(r.acceptanceCriterion)}</div></div><div class="trace"><div class="trace-step"><small>Source</small><strong>${r.sourceId}</strong></div><div class="trace-step"><small>Controlled spec</small><strong>${o.sp?`${o.sp.id} Rev ${o.sp.revision}`:'No spec'}</strong></div><div class="trace-step"><small>Validation requirement</small><strong>${r.id}</strong></div><div class="trace-step"><small>Coverage method</small><strong>${methods.map(m=>m.id).join(', ')||'Gap'}</strong></div><div class="trace-step"><small>Test legs</small><strong>${o.legs.map(l=>l.id).join(', ')||'Not covered'}</strong></div><div class="trace-step"><small>DUTs</small><strong>${new Set(o.legs.flatMap(l=>l.dutIds)).size} assigned</strong></div><div class="trace-step"><small>Evidence</small><strong>${results.length} results</strong></div><div class="trace-step"><small>Status</small><strong>${r.status}</strong></div></div><div class="grid kpi compact-kpis">${kpiCard('Criticality',r.criticality,r.category)}${kpiCard('Operational action',o.action,'Next control step')}${kpiCard('Forecast coverage cost',currency(state,o.estimatedCost,true),o.legs.length?'linked legs':'indicative suggested method')}${kpiCard('Method state',methods[0]?(methods[0].active?'Exists / Released':'Needs Development'):'No method','Test Library readiness')}</div>${o.sp?`<div class="callout ${o.sp.status==='Released'?'':'warning'}"><strong>Specification basis:</strong> ${o.sp.id} Rev ${esc(o.sp.revision)} · ${o.sp.status} · quality ${o.sp.qualityScore}%. ${o.sp.status!=='Released'?'Future execution remains gated until a released basis exists.':''}</div>`:''}<h3>Coverage legs</h3><div class="table-wrap"><table><thead><tr><th>Leg</th><th>Method</th><th>DUTs</th><th>Planned</th><th>Resources</th><th>Cost</th><th>Status</th></tr></thead><tbody>${o.legs.map(l=>{const C=estimateLegCost(state,l),m=state.methods.find(x=>x.id===l.methodId);return`<tr><td><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span></td><td>${m?.id} · ${esc(m?.name||'')}</td><td>${l.dutIds.length}</td><td>${fmtDate(l.plannedStart,true)}</td><td>${l.equipmentId||'—'} / ${state.staff.find(s=>s.id===l.staffId)?.name||'—'}</td><td>${currency(state,C.total,true)}</td><td>${pill(l.status)}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No coverage has been created.</td></tr>'}</tbody></table></div>${results.length?`<h3>Objective evidence</h3><div class="table-wrap"><table><thead><tr><th>Result</th><th>DUT</th><th>Parameter</th><th>Value</th><th>Status</th><th>Evidence</th></tr></thead><tbody>${results.slice(0,25).map(x=>`<tr><td>${x.id}</td><td>${x.dutId}</td><td>${esc(x.parameter)}</td><td>${esc(x.value)} ${esc(x.unit||'')}</td><td>${pill(x.status)}</td><td>${x.evidenceId||'—'}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="actions" style="margin-top:14px"><button id="manageReqCoverage" class="btn primary">${o.legs.length?'Manage / Add Coverage':'Create Test Coverage'}</button>${o.sp?`<button id="openReqSpec" class="btn">Open Specification</button>`:''}</div>`);wireEntities(modalBody);document.getElementById('manageReqCoverage').onclick=()=>coverRequirementModal(id);if(o.sp)document.getElementById('openReqSpec').onclick=()=>showSpecification(o.sp.id)}

function showProgramme(id){const p=state.programmes.find(x=>x.id===id),ls=state.legs.filter(l=>l.programmeId===id),req=state.requirements.filter(r=>r.programmeId===id),duts=state.duts.filter(d=>d.programmeId===id),spec=state.specifications?.find(s=>s.programmeId===id);if(!p)return;const C=programmeCost(state,id),R=programmeReadiness(id),newMethods=ls.filter(l=>!state.methods.find(m=>m.id===l.methodId)?.active),issues=(state.issues||[]).filter(i=>i.programmeId===id);openModal(`<h2>${p.id} · ${esc(p.project)}</h2><div class="detail-grid"><div class="detail"><small>Customer</small><strong>${esc(p.customer)}</strong></div><div class="detail"><small>Product</small><strong>${esc(p.product)} ${p.productRevision}</strong></div><div class="detail"><small>Priority / Risk</small><strong>${p.priority} · ${p.scheduleRisk}</strong></div><div class="detail"><small>Programme gate</small><strong>${p.gateStatus||'Released'}</strong></div><div class="detail"><small>Due / Forecast</small><strong>${fmtDate(p.dueDate)} → ${fmtDate(p.forecastCompletion)}</strong></div><div class="detail"><small>Owner</small><strong>${esc(p.owner)}</strong></div><div class="detail"><small>Specification</small><strong>${spec?`${spec.id} Rev ${spec.revision} · ${spec.status}`:'—'}</strong></div><div class="detail"><small>Release readiness</small><strong>${R.score}%</strong></div></div><h3>Cost position</h3><div class="grid kpi compact-kpis">${kpiCard('Estimated',currency(state,C.estimated.total,true),'Baseline programme cost')}${kpiCard('Actual to date',currency(state,C.actualToDate,true),'Completed execution')}${kpiCard('Forecast at completion',currency(state,C.forecast,true),`budget ${currency(state,C.budget,true)}`)}${kpiCard('Budget variance',`${C.variance>=0?'+':''}${currency(state,C.variance,true)}`,`${C.variancePct>=0?'+':''}${C.variancePct}%`)}</div><div class="callout warning"><strong>Demo storyline:</strong> ${esc(p.storyline)}</div><h3>Release readiness</h3>${R.checks.map(x=>`<div class="checkline"><span class="${x.ok?'diag-pass':'diag-fail'}">${x.ok?'PASS':'CHECK'}</span><strong>${esc(x.name)}</strong><span class="small muted">${esc(x.detail)}</span></div>`).join('')}<h3>Test programme legs</h3><div class="tree">${ls.map(l=>{const m=state.methods.find(x=>x.id===l.methodId),lc=estimateLegCost(state,l);return `<div class="tree-item"><span>${l.sequence}</span><strong class="link" data-entity="leg" data-id="${l.id}">${l.id}</strong><span>${esc(l.name)}</span><span class="small muted">${m?.active?'Existing':'Develop'} · ${currency(state,lc.total,true)}</span>${pill(l.status)}</div>`}).join('')}</div><h3>Coverage & operating history</h3><p class="small">${req.length} requirements · ${duts.length} DUTs · ${req.filter(r=>r.status==='Verified').length} verified · ${req.filter(r=>r.status==='Failed').length} failed · ${newMethods.length} legs use unreleased methods · ${issues.length} recorded issues.</p>`) }
